// share no memory with an input or another output.
//
// The errors are those of [Core.PLUS_DMOpen], and [BadParam] for an output that
// is empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) PLUS_DMOpenAndFill(inHigh, inLow []float64, optInTimePeriod int, outReal []float64) (*PLUS_DMStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.plusDmLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inHigh) || sameStart(outReal, inLow) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outReal, inHigh) || overlaps(outReal, inLow)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.plusDmOpenAndFillInternal(inHigh, inLow, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
